<script setup>
import { ref,computed,watch,onBeforeUnmount } from 'vue';
import { requestVisitReport } from '../../api/cc-visit-report';
import { indiaStamp, visitStatus } from '../../lib/cc';
import { businessCycle,cycleDays } from '../../lib/cc-visit-report';
const props=defineProps({branch:String,agent:String,refreshKey:Number});const emit=defineEmits(['select']);
const anchor=indiaStamp().slice(0,10),offset=ref(0),rows=ref([]),busy=ref(false),error=ref(''),partial=ref(false);let generation=0,controller,previousRefresh;
const days=computed(()=>cycleDays(anchor,offset.value)),range=computed(()=>businessCycle(anchor,offset.value));
const counts=computed(()=>{const output={};for(const row of rows.value){if(props.branch&&(row.branch||row.lead_assign_to_branch)!==props.branch||props.agent&&row.lead_owner!==props.agent)continue;const key=String(row.day||row.custom_appointment_date_and_time).slice(0,10);const item=output[key]||={appointments:0,visits:0,booked:0};const count=Number(row.count??1);item.appointments+=count;if(visitStatus(row).startsWith('Visited'))item.visits+=count;if(visitStatus(row)==='Visited-BKD')item.booked+=count;}return output;});
async function load(){const refresh=previousRefresh!==props.refreshKey;previousRefresh=props.refreshKey;const token=++generation;controller?.abort();controller=new AbortController();busy.value=true;error.value='';rows.value=[];try{const data=await requestVisitReport({view:'calendar',from_date:range.value[0],to_date:range.value[1]},controller.signal,refresh);if(token!==generation)return;rows.value=data.days||[];partial.value=!!data.truncated;}catch(e){if(token===generation&&e.name!=='AbortError')error.value=e.message;}finally{if(token===generation)busy.value=false;}}
watch(()=>[offset.value,props.refreshKey],load,{immediate:true});onBeforeUnmount(()=>{generation++;controller?.abort();});
</script>
<template><section class="cc-month-strip" aria-label="Daily appointment strip"><header><button :disabled="busy" aria-label="Previous business month" @click="offset--">‹</button><strong>{{range[0]}} → {{range[1]}}</strong><button :disabled="busy" aria-label="Next business month" @click="offset++">›</button><span>Appointments · Visits / Booked</span></header><p v-if="error" role="alert">{{error}} <button @click="load">Retry</button></p><p v-if="partial" role="alert">Partial calendar totals. Narrow the report dates for complete detail.</p><div class="cc-month-scroll"><table :aria-busy="busy"><thead><tr><th scope="col">Date</th><th v-for="day in days" :key="day" scope="col" :class="{today:day===anchor}"><button :aria-label="'Show appointments for '+day" @click="emit('select',day)">{{day.slice(8)}}<small>{{new Date(day+'T12:00:00Z').toLocaleDateString('en-GB',{weekday:'short',timeZone:'Asia/Kolkata'})}}</small></button></th></tr></thead><tbody><tr><th scope="row">Appointments</th><td v-for="day in days" :key="day">{{busy?'…':counts[day]?.appointments||'·'}}</td></tr><tr><th scope="row">Visits / Booked</th><td v-for="day in days" :key="day">{{busy?'…':`${counts[day]?.visits||0}/${counts[day]?.booked||0}`}}</td></tr></tbody></table></div></section></template>
<style scoped>.cc-month-strip{background:#fffdf5;border:1px solid #d5b66b;border-radius:10px;margin:10px 0;overflow:hidden}.cc-month-strip header{display:flex;align-items:center;flex-wrap:wrap;gap:10px;padding:8px;color:#174b30;font-size:12px}.cc-month-strip button{background:transparent;color:inherit;border:0;cursor:pointer}.cc-month-scroll{overflow:auto}table{border-collapse:collapse;min-width:1050px;width:100%;font-size:11px}th,td{text-align:center;border:1px solid #e5dfd0;padding:5px}th{background:#f7f1df}th:first-child{min-width:100px}small{display:block;font-size:9px;color:#777}.today{background:#d5b66b}</style>
